UPDATE fcc_extension
SET agent_work_no = NULL, agent_name = NULL
WHERE agent_work_no = #{owner} OR extension = #{extension}

UPDATE fcc_agent
SET current_extension = NULL
WHERE work_no = #{owner} OR current_extension = #{extension}

UPDATE fcc_agent
SET current_extension = #{extension}
WHERE work_no = #{owner} AND status = 'ENABLED' AND deleted_at IS NULL

mapper.insert:
INSERT INTO fcc_agent_endpoint_binding(
  id, agent_id, endpoint_type, extension_id, endpoint_value, priority, status
)
SELECT #{id}, a.id, 'SIP', e.id, e.extension, 1, 'ENABLED'
FROM fcc_agent a
JOIN fcc_extension e ON e.extension = #{extension}
WHERE a.work_no = #{owner}
  AND a.deleted_at IS NULL
  AND e.deleted_at IS NULL
